+
+@SpringBootTest
+public class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void headingsAndLink() {
+        navigate(ContactView.class);
+        assertEquals("Contact", find(H1.class).first().getText());
+
+        test(find(RouterLink.class).first()).navigate();
+        assertEquals("About", find(H1.class).first().getText());
+    }
+
+    @Test
+    void sendButtonEnabledOnEmptyForm() {
+        navigate(ContactView.class);
+        Button send = find(Button.class).withText("Send").first();
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void validationBlocksEmptyForm() {
+        navigate(ContactView.class);
+        int countBefore = find(Grid.class).first().getListDataView().getItemCount();
+
+        Button send = find(Button.class).withText("Send").first();
+        test(send).click();
+
+        TextField name = find(TextField.class).withLabel("Name").first();
+        EmailField email = find(EmailField.class).first();
+        TextArea message = find(TextArea.class).first();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        assertEquals(countBefore, find(Grid.class).first().getListDataView().getItemCount());
+    }
+
+    @Test
+    void invalidEmailFormat() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").first();
+        EmailField email = find(EmailField.class).first();
+        TextArea message = find(TextArea.class).first();
+
+        test(name).setValue("Jane");
+        test(email).setValue("not-an-email");
+        test(message).setValue("hello");
+
+        Button send = find(Button.class).withText("Send").first();
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+    }
+
+    @Test
+    void successfulSendWithPhoneOnly() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").first();
+        TextField phone = find(TextField.class).withLabel("Phone").first();
+        TextArea message = find(TextArea.class).first();
+        Button send = find(Button.class).withText("Send").first();
+
+        test(name).setValue("Jane");
+        test(phone).setValue("12345");
+        test(message).setValue("hello there");
+
+        test(send).click();
+
+        Notification notification = find(Notification.class).first();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertEquals("", name.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+
+        assertFalse(send.isEnabled());
+
+        Grid<?> grid = find(Grid.class).first();
+        assertEquals(1, test(grid).size());
+
+        test(name).setValue("x");
+        assertTrue(send.isEnabled());
+    }
+
